// ── WHERE THE NEXT TURN WILL RUN ───────────────────────────
//
// The election was invisible. A turn left for another machine, or stayed here, and
// the only way to find out which was to send it and watch: nothing on screen said
// what the next send would do. On a phone that is not a cosmetic gap -- a turn that
// runs locally needs the app kept in the foreground and the screen awake, and the
// user can only plan for that if they are told BEFORE they commit to it (owner spec
// 2026-09-12). One line under the composer, written from the latest beats and
// redrawn on every presence change and nomination change.

/// The options the seat switch's decision is taken with: the SAME ones
/// `maybeAutoDispatch` passes, so the line cannot promise a seat the send would not
/// take. `selfMobile` is the extra -- the line needs to know whether running HERE is
/// something the user must act on.
export function seatOpts(chat) {
	var c = chat || pg.current;
	return {
		selfId:         selfDeviceId(),
		isPhone:        isPhoneViewport(),
		selfMobile:     isMobileDeviceSelf(),
		preferredLabel: preferredWorkerLabel(),
		currentBuild:   fleetCurrentBuild(),
		nominatedId:    (typeof nominatedDeviceId === 'function') ? nominatedDeviceId() : '',
		globalDefault:  handoffWhenAway(),
		freshWindowMs:  DaimondPeer.DISPATCH_FRESH_MS,
		toggle:         (c && chatSeatHere(c)) ? false : null,
		needFolder:     chatNeedsFolder(c),
		runnerOnly:     true,
		provider:       electProvider(c),
		sources:        electSources(c),
		// A re-read did not land (a gateway restart): the map is unknown and seats nobody.
		presenceUnknown: !!(window.DaimondPresence && DaimondPresence.unknown && DaimondPresence.unknown()),
	};
}

/// The provider an election judges `chat` by: the one its turn will run on, which is the
/// one its errand carries (`errandModelOf`), not the stored pick. A chat that follows the
/// default stores `''` (U1c), and judged by that a native runner, which serves credits only
/// (peer.js recEngineOk), was never offered a default-following chat even with the default
/// on credits (QA-B #3). '' only when nothing resolves.
function electProvider(chat) {
	try { return chat ? String(errandModelOf(chat).provider || '') : ''; }
	catch (e) { return ''; }
}

/// Every source `chat`'s turn pays with, across its halves (OWNKEY §2.2): the turn's own,
/// its workers' and its images', as its errand carries them. A runner is offered only when
/// it can use each one (peer.js recEngineOk). [] only when nothing resolves.
function electSources(chat) {
	var m = null;
	try { m = chat ? errandModelOf(chat) : null; } catch (e) { m = null; }
	var out = [];
	[m, m && m.workers, m && m.images].forEach(function (h) {
		var p = (h && h.provider) ? String(h.provider) : '';
		if (p && out.indexOf(p) < 0) out.push(p);
	});
	return out;
}

/// Is this chat's folder ROOTED on this device (F4c, UNBLOCK-32): the real folder open
/// here, and a mark of its Diamond or a workspace holding of its own pressed in it? Then
/// the turn runs only where a folder is held too, since a runner with none reaches none
/// of it and a switch that offers one which then cannot do the turn is a fault (§1).
export function chatNeedsFolder(chat) {
	// A Diamond naming its own folder (HATE-7) needs no workspace folder held at the runner.
	if (chat && chat.diamondId && diamondFolder(chat.diamondId)) return false;
	if (!chat || !selfHoldsFolder() || !window.DaimondMarksHere || !DaimondMarksHere.rootedHere) return false;
	try { return DaimondMarksHere.rootedHere(chat.diamondId || '', chat.id || '', rootHere()); }
	catch (e) { return false; }
}

// ── THE PERSON'S CHOICE, per chat (owner, D-20261009-23) ──
//
// "Here" pins a chat to the device it is sent from; the runner segment lets the
// runner take it. Sticky per chat and kept on this device: "Here" means this
// device, so another device's choice for the same chat is not this one's.
var SEAT_HERE_KEY = 'daimond-seat-here';		// { chatId: 1 } for chats pinned here

function seatHereMap() {
	try { return JSON.parse(localStorage.getItem(SEAT_HERE_KEY) || '{}') || {}; }
	catch (e) { return {}; }
}

/// Is `chat` pinned to run here?
export function chatSeatHere(chat) {
	var id = chat && chat.id ? String(chat.id) : '';
	return !!id && !!seatHereMap()[id];
}

function setChatSeatHere(chat, here) {
	var id = chat && chat.id ? String(chat.id) : '';
	if (!id) return;
	var m = seatHereMap();
	if (here) m[id] = 1; else delete m[id];
	try { localStorage.setItem(SEAT_HERE_KEY, JSON.stringify(m)); } catch (e) { /* this session only */ }
}

/// The runner the "Here | <runner>" switch draws pressed for `chat` now, by its label, or ''
/// where it draws Here or no runner (`renderSeatSwitch` draws from the same `seatSwitchFor`).
///
/// THE PERSON'S CHOICE IS WHAT THE SWITCH DREW AT THE PRESS (rulings §1 l.9, l.18; SUHT-R
/// killrunner). Read once, at the press of Send or Retry and before any presence read can
/// redraw the switch, and carried to the send's end: a runner drawn then and gone by the
/// send-time read ends "not run" (`endSendNotRun`); a switch already drawing Here runs the
/// turn here. A runner that stopped being drawn before the press is not the person's choice:
/// it was remembered until they pressed Here, and every Retry after the runner died ended
/// "not run" behind a switch reading plain Here.
export function seatDrawnRunner(chat) {
	var sw = seatSwitchFor(chat);
	if (!sw || sw.choice !== 'runner' || !sw.runner) return '';
	return deviceLabelFor(sw.runner.deviceId) || sw.runner.label || t('devices.unknown');
}

/// Put the "ran here" line on a person's message tile.
export function drawSeatNote(tile, text) {
	if (!tile || !tile._body || !text) return;
	var el = document.createElement('div');
	el.className = 'seat-note seat-warn';
	el.textContent = text;
	tile._body.appendChild(el);
}

/// The name a seat note gives a device: its label, the name it was sent under, or
/// "unknown device". The status code behind a refusal stays on the tooltip.
export function seatNameOf(id, name) {
	return (id && deviceLabelFor(id)) || (name ? String(name) : '') || t('devices.unknown');
}

/// The plan as it stands right now, or null when nothing can be said (no chat open,
/// the peer module not up, this device not yet identified).
export function seatPlanNow() {
	try {
		if (!window.DaimondPeer || !DaimondPeer.seatPlan) return null;
		// A daimon chat now seats like any other: `renderSeatSwitch` draws "Runs on
		// <device>" for it, because a daimon turn dispatches. `seatOpts()` reads the
		// daimon chat's own toolsEnabled/runOnPeer, so the pure `seatPlan` decides it
		// the same way it decides a chat.
		if (!pg.current) return null;
		var o = seatOpts();
		if (!o.selfId) return null;
		o.queueOn = chatRunningOn(pg.current);	// as the send reads it
		var presence = turnPresence((window.DaimondPresence && DaimondPresence.snapshot()) || {});
		return DaimondPeer.seatPlan(pg.current, presence, o, Date.now());
	} catch (e) { return null; }
}

/// What the "Here | <runner>" switch reads for `chat`, from the options and presence the
/// send reads, or null. The switch draws it and a follow-up typed into a running turn
/// obeys it (`sendPressed`), so the two cannot disagree.
export function seatSwitchFor(chat) {
	try {
		if (!chat || !window.DaimondPeer || !DaimondPeer.seatSwitch) return null;
		var o = seatOpts(chat);
		if (!o.selfId) return null;
		// A runner busy with THIS chat is still offered: the send queues there (O3).
		o.queueOn = chatRunningOn(chat);
		// The presence the send reads (`maybeAutoDispatch`): a claim this device
		// sees on another chat makes the runner busy before its own beat says so.
		var presence = presenceWithLeaseBusy(turnPresence(
			(window.DaimondPresence && DaimondPresence.snapshot()) || {}), chat);
		return DaimondPeer.seatSwitch(chat, presence, o, Date.now());
	} catch (e) { return null; }
}

/// Does the switch name a runner for `chat`, so its next turn is the runner's and not this device's?
export function seatNamesRunner(chat) {
	var sw = seatSwitchFor(chat);
	return !!(sw && sw.choice === 'runner' && sw.runner);
}

/// Draw (or hide) the "Here | <runner>" switch by the input box (owner, D-20261009-23,
/// restated 2026-10-11: "down near the input box where the users eyes are"). Cheap and idempotent: it reads the live
/// snapshot, takes the pure decision and sets two buttons, so it can be called on
/// every presence beat without thought.
var _seatWhyOpen = '';	// the reason (its key tail) whose sentence a tap has opened in place

export function renderSeatSwitch() {
	var box  = document.getElementById('seat-switch');
	var here = document.getElementById('seat-here');
	var run  = document.getElementById('seat-runner');
	if (!box || !here || !run) return;
	var sw = seatSwitchFor(pg.current);
	// SEATWHY: one line beside a plain "Here" when the nominated runner is held off by a
	// rule the person can act on -- it serves credits only, or it runs another engine.
	// SEAT-LABELS: the label beside the seat, the sentence on hover and, tapped, in its place.
	var why = document.getElementById('seat-reason');
	if (why) {
		var r = seatReason(seatWhyKey(sw));
		if (!r || r.k !== _seatWhyOpen) _seatWhyOpen = '';
		var open = !!r && _seatWhyOpen === r.k;
		why.textContent = r ? (open ? r.why : r.label) : '';
		why.title = r ? r.why : '';
		why.setAttribute('aria-label', r ? r.why : '');
		why.setAttribute('aria-expanded', open ? 'true' : 'false');
		why.dataset.why = r ? r.k : '';
		why.hidden = !r;
	}
	// R4: one timer, at the moment the runner stops counting as reachable on the beat
	// it has, so the switch already reads Here when the person sends. A beat, a claim
	// or a release redraws through its own event and re-arms it.
	armSeatSwitchTimer(sw && sw.runner ? sw.until : 0);
	// On a single-device account "Here" is the only place a turn could ever run, so
	// the switch would say nothing (CHAT-07/PH-06). `loadDevices()`, not
	// `collectDevices()`, which writes the roster on every call.
	if (!sw || (!sw.runner && Object.keys(loadDevices()).length <= 1)) {
		box.hidden = true;
		return;
	}
	var onRunner = sw.choice === 'runner';
	here.setAttribute('aria-pressed', onRunner ? 'false' : 'true');
	if (sw.runner) {
		run.textContent = deviceLabelFor(sw.runner.deviceId) || sw.runner.label || t('devices.unknown');
		run.title = run.textContent;	// whole, where the row cuts it short
		run.dataset.device = sw.runner.deviceId;
		run.setAttribute('aria-pressed', onRunner ? 'true' : 'false');
		run.hidden = false;
	} else {
		run.hidden = true;
		run.textContent = '';
		run.title = '';
		delete run.dataset.device;
	}
	box.hidden = false;
}

/// THE ONE SEAT-REASON RENDERER (SEAT-LABELS; owner, 25 Oct: "wtf is this ridiculously long
/// explanation?"): the reason `{ k, vars }` as its 2-4 word label, drawn beside the seat, and its
/// sentence, the hover title and the tap. `k` is the tail of a `seat.why_` key. Every seat reason
/// the page shows is read here and nowhere else, so none can bypass its label
/// (seatlabels.test.mjs holds every key to a label in every locale). Null for no reason.
export function seatReason(r) {
	if (!r || !r.k) return null;
	return { k: r.k, label: t('seat.label_' + r.k, r.vars), why: t('seat.why_' + r.k, r.vars) };
}

/// The switch's reason (SEATWHY, OWNKEY §5.2) as `{ k, vars }` for `seatReason`, or null when it
/// names none: the source the runner cannot use and why, the re-approval a passphrase change
/// needs, another engine (it updates itself), a page older than the runner, a legacy runner's
/// credits only, or a seating rule (SEATWHY-ALL).
function seatWhyKey(sw) {
	if (!sw || !sw.why) return null;
	var name = deviceLabelFor(sw.runnerId) || t('devices.unknown');
	var v = { name: name };
	switch (sw.why) {
		case 'runner-source':
			var M = window.DaimondModels;
			return { k: 'runner_source', vars: { name: name,
				provider: (M && M.providerName) ? M.providerName(sw.source) : String(sw.source || ''),
				reason:   t('seat.reach_' + (sw.reach || 'nokey')) } };
		case 'runner-rekey':		return { k: 'runner_rekey',		vars: v };
		case 'runner-engine':		return { k: 'runner_engine',		vars: v };
		case 'runner-credits-only':	return { k: 'runner_credits',		vars: v };
		case 'runner-silent':		return { k: 'runner_quiet',		vars: v };
		case 'runner-busy':		return { k: 'runner_busy',		vars: v };
		case 'runner-phone':		return { k: 'runner_phone',		vars: v };
		case 'runner-require':		return { k: 'runner_require',		vars: v };
		case 'runner-nosource':	return { k: 'runner_nosource',	vars: v };
		case 'runner-unchecked':	return { k: 'runner_unchecked',	vars: v };
		case 'page-old':			return { k: 'page_old',			vars: v };
		default:					return null;
	}
}

// WHY A TURN DID NOT RUN (NOTRUN-WHY): a "not run" row's cause, the tail of its `seat.why_`
// key. A runner's hand-back cause by its own name, and the page's own: `size` (an errand over
// what the runner reads), `unable`, `gone`, `unclaimed`, `released`, `unchecked`, `post`. Three
// are a switch reason already and are said the same way.
var NOTRUN_KEYS = {
	'size':          'notrun_size',
	'door':          'notrun_door',
	'thread':        'notrun_thread',
	'models':        'notrun_models',
	'models-behind': 'notrun_models_behind',
	'refused':       'notrun_refused',
	'place':         'notrun_place',
	'busy':          'notrun_busy',
	'unable':        'notrun_unable',
	'gone':          'notrun_gone',
	'unclaimed':     'notrun_unclaimed',
	'released':      'notrun_released',
	'unchecked':     'notrun_unchecked',
	'post':          'notrun_post',
	'oversize':      'notrun_oversize',
	'abi':           'runner_engine',
	'limits':        'page_old',
	'keys':          'runner_rekey',
};

/// A "not run" cause as the row keeps it, `{ cause, to, name, said }`: the runner it was sent
/// to by id and by the name known now, and the runner's own words where it gave them. Null for
/// a cause this page has no words for, which leaves the row's plain "not run".
export function notRunCause(cause, to, name, said) {
	var c = String(cause || '');
	if (!NOTRUN_KEYS[c]) return null;
	var id = String(to || '');
	var nm = String(name || '') || (id ? deviceNameFor(id) : '');
	return { cause: c, to: id, name: nm, said: said ? String(said) : '' };
}

/// A "not run" row's reason (`m.notRun`) as `{ k, vars }` for `seatReason`, or null where it
/// names no cause (a row written before causes, or a throw), which keeps the plain words.
export function notRunWhyKey(nr) {
	var k = nr && NOTRUN_KEYS[String(nr.cause || '')];
	if (!k) return null;
	var name = (nr.to ? deviceNameFor(nr.to) : '') || String(nr.name || '') || t('devices.another');
	return { k: k, vars: { name: name } };
}

/// The wasm's engine ABI as `[abi, min]`, from its one export `engine_abi()` (a Uint32Array
/// of two). A build that predates it, or answers anything but two whole numbers with the
/// min no higher than the abi, is legacy: `[0, 0]`.
function wasmEngineAbi(W) {
	var v = null;
	try { v = (W && typeof W.engine_abi === 'function') ? W.engine_abi() : null; } catch (e) { v = null; }
	if (!v || typeof v.length !== 'number' || v.length !== 2) return [0, 0];
	var abi = v[0], min = v[1];
	var whole = function (n) { return typeof n === 'number' && n >= 0 && n === Math.floor(n) && n <= 0xffffffff; };
	if (!whole(abi) || !whole(min) || min > abi) return [0, 0];
	return [abi, min];
}

/// The wasm's first runner ABI that stages his words home (`words_abi()`), 0 from a build that
/// predates it or answers anything but a whole number from 1.
function wasmWordsAbi(W) {
	var v = 0;
	try { v = (W && typeof W.words_abi === 'function') ? W.words_abi() : 0; } catch (e) { v = 0; }
	return (typeof v === 'number' && v >= 1 && v === Math.floor(v) && v <= 0xffffffff) ? v : 0;
}

/// THIS PAGE'S ENGINE ID (R5a, X12): the sha-256 of the wasm it runs, read back from
/// the cache the module was loaded from. A native runner is offered on the switch only
/// when the id stamped into it at its release build is this one; until it is known,
/// none is.
export async function learnEngineId() {
	// THE ENGINE ABI (OWNKEY ABI-a) first, read from the wasm and guarded for a build that
	// predates it: 0 offers a runner by the legacy rule and writes no `abi`.
	if (window.DaimondPeer && DaimondPeer.setEngineAbi) {
		var ab = wasmEngineAbi(Wasm);
		DaimondPeer.setEngineAbi(ab[0], ab[1], wasmWordsAbi(Wasm));
		// The offer is decided again now the page's side is known: until this line every ABI
		// runner read "not checked yet" (SEAT-LABELS truth).
		renderSeatSwitch();
	}
	if (!window.DaimondPeer || !DaimondPeer.setEngineId || !(window.crypto && crypto.subtle)) return;
	var res = await fetch(new URL('../../pkg/oxedyne_daimond_bg.wasm' /* page-split: rebased */, import.meta.url), { cache: 'force-cache' });
	if (!res.ok) return;
	var d = new Uint8Array(await crypto.subtle.digest('SHA-256', await res.arrayBuffer()));
	var hex = '';
	for (var i = 0; i < d.length; i++) hex += (d[i] < 16 ? '0' : '') + d[i].toString(16);
	DaimondPeer.setEngineId(hex);
	renderSeatSwitch();
}

var _seatSwitchTimer = null;
function armSeatSwitchTimer(until) {
	if (_seatSwitchTimer) { clearTimeout(_seatSwitchTimer); _seatSwitchTimer = null; }
	if (!(until > 0)) return;
	_seatSwitchTimer = setTimeout(function () { _seatSwitchTimer = null; renderSeatSwitch(); },
		Math.max(0, until - Date.now()));
}

/// The person presses a segment: the choice is the chat's, before it is sent.
function chooseSeat(here) {
	if (!pg.current) return;
	setChatSeatHere(pg.current, here);
	renderSeatSwitch();
}
// page-split: install 64

/// What the composer's Effort step stands for: the chat's own Effort, or on a Diamond's face
/// the daimon's, which is the Diamond's own (one door, D-20261014-08 F2).
function effortHolder() {
	if (!pg.current) return null;
	if (pg.current.diamondId) {
		var m = diamondModel(pg.current.diamondId);
		return { diamond: pg.current.diamondId, provider: m.provider || '', model: m.model || '',
			effort: diamondEffort(pg.current.diamondId) };
	}
	// The pair in force, which is the default's for a chat that follows it (U1c).
	var r = window.DaimondModels && DaimondModels.resolve(pg.current.provider || '', pg.current.model || '');
	return { chat: pg.current, provider: r ? r.provider : (pg.current.provider || ''),
		model: r ? r.model : (pg.current.model || ''), effort: pg.current.effort || '' };
}

/// The step's ladder. A model that names its default stands at that level when the Effort is
/// '' (the level's own name, in muted ink); one that names none has a "Default" rung below.
function effortLadder(f) {
	return f.dflt ? f.levels.slice() : [''].concat(f.levels);
}

/// Draw (or hide) the Effort step in the composer row (D-20261014-08): how hard the next
/// turn on screen thinks, over its model's levels. Hidden for a model that lists none.
export function renderEffortStep() {
	// The source names the same record's model, so whatever moves one moves the other.
	renderSourceSwitch();
	var box = document.getElementById('effort-step');
	var dn  = document.getElementById('effort-dn');
	var up  = document.getElementById('effort-up');
	var val = document.getElementById('effort-val');
	if (!box || !dn || !up || !val) return;
	var h = effortHolder(), f = null;
	if (h) {
		try { f = DaimondModels.effortsFor(h.provider, h.model); } catch (e) { f = null; }
	}
	if (!f || !f.levels || !f.levels.length) { box.hidden = true; return; }
	var steps = effortLadder(f);
	var i = Math.max(0, steps.indexOf(h.effort || f.dflt));
	var lvl = steps[i];
	var dflt = !h.effort;					// the model's own default, whatever it is named
	val.textContent = lvl ? t('tile.effort_' + lvl) : t('composer.effort_default');
	val.title = dflt ? (f.dflt ? t('tile.effort_default_named', { level: t('tile.effort_' + f.dflt) })
		: t('tile.effort_default')) : t('tile.effort_help');
	val.classList.toggle('is-default', dflt);
	dn.disabled = i <= 0;
	up.disabled = i >= steps.length - 1;
	box.hidden = false;
}

/// A press of − or +: the Effort moves one step, landing on the model's own default as ''.
///
/// NO ENGINE CALL HERE (F3). `runTurn` and `diamondApp` put the Effort on the engine at each
/// turn's start, and the engine reads it on every request, so a press while a turn runs would
/// change that turn's remaining rounds while its record kept the old level. It is the next
/// turn's.
function stepEffort(by) {
	var h = effortHolder();
	if (!h) return;
	var f = null;
	try { f = DaimondModels.effortsFor(h.provider, h.model); } catch (e) { return; }
	if (!f || !f.levels || !f.levels.length) return;
	var steps = effortLadder(f);
	var i = Math.max(0, steps.indexOf(h.effort || f.dflt));
	var j = Math.min(steps.length - 1, Math.max(0, i + by));
	if (j === i) return;
	var next = steps[j] === f.dflt ? '' : steps[j];
	if (h.diamond) {
		setDiamondEffort(h.diamond, next);
		// THE DIAMOND'S EFFORT TRAVELS on the record's own stamp, in every parcel round
		// (`adoptDiamondModel`). Never by touching the Diamond: that won a whole-Diamond race
		// and put another device's crystal edit off the head (check_f1 B1).
		bumpDiamonds();
	} else {
		h.chat.effort = next;
		// The model half, on its own stamp with the model it belongs to (U1c).
		touchChatModel(h.chat);
		persistChats();
	}
	renderEffortStep();
}
