/// THE ELECTION SMOKING-GUN, for the opt-in diagnostics ring. Renders exactly
/// what `autoDispatchDecision` saw and chose, so a hand-off to the wrong device
/// is diagnosable from the phone that made it: every peer in the snapshot with
/// its beat age, servicing age, and genuine? verdict; the nominated runner and
/// whether it is even present in this device's snapshot; and the decision's
/// reason and chosen peer. This is what tells a stale snapshot from a nominee-id
/// mismatch from an argonaut simply absent from iOS's presence. Ids only (short),
/// device labels, ages and counts -- never content. A no-op when Diagnostics is
/// off; built only when it is on, so the string work is not paid otherwise.
function electionTrace(presence, self, nominee, decision, win) {
	if (!window.DaimondDiag || !DaimondDiag.on()) return '';
	var now = Date.now();
	var w = win || (window.DaimondPeer && DaimondPeer.DISPATCH_FRESH_MS) || 90000;
	function ms(v) { return (v && typeof v.toNumber === 'function') ? v.toNumber() : (Number(v) || 0); }
	var peers = [], nomPresent = false;
	Object.keys(presence || {}).forEach(function (id) {
		var rec = presence[id];
		if (!rec) return;
		if (id === String(self || '')) { peers.push(id.slice(0, 8) + '(self)'); return; }
		if (id === String(nominee || '')) nomPresent = true;
		var beat = Math.round((now - ms(rec.lastSeen)) / 1000);
		var svc  = (rec.servicedAt != null) ? (Math.round((now - ms(rec.servicedAt)) / 1000) + 's') : 'n/r';
		var genuine = false;
		try { genuine = !!(DaimondPeer.recGenuine && DaimondPeer.recGenuine(rec, now, w)); } catch (e) {}
		var bd = rec.build ? (' build=' + String(rec.build).slice(0, 7)) : '';
			peers.push((rec.name || id.slice(0, 8)) + '[' + id.slice(0, 8)
			+ ' beat=' + beat + 's svc=' + svc + ' genuine=' + (genuine ? 'Y' : 'N') + bd + ']');
	});
	var nomStr = nominee
		? (String(nominee).slice(0, 8) + (nomPresent ? ' PRESENT' : ' ABSENT-from-snapshot'))
		: 'none';
	var dpeer = (decision && decision.peer)
		? ((decision.peer.name || '') + '/' + String(decision.peer.deviceId || '').slice(0, 8)) : '-';
	return 'self=' + String(self || '').slice(0, 8) + ' nominee=' + nomStr
		+ ' peers=[' + peers.join(' ') + ']'
		+ ' -> dispatch=' + (decision && decision.dispatch ? 'YES' : 'no')
		+ ' reason=' + (decision && decision.reason) + ' peer=' + dpeer
		+ (decision && decision.staleBuild ? ' STALE-BUILD-PEER' : '');
}

// When each hand-off began, keyed by turn id, so the answer's arrival can be
// timed against the send. Bounded: entries are deleted when the placeholder is
// reconciled, and the map is a handful of live turns.
export var _handoffStart = {};

// The election trace this device recorded for each live dispatched turn, so the
// answer-arrival auto-log (below) can report the advertised target against the
// device that actually claimed it, and how long the correction took. Keyed by
// turnId; entries are dropped when the answer merges. A handful of live turns.
export var _electionTrace = Object.create(null);

/// Coerce a lease-clock value (which may be a bignum with `toNumber`) to a plain
/// millisecond number, matching the reader `electionTrace` and peer.js use.
function _msNum(v) {
	return (v && typeof v.toNumber === 'function') ? v.toNumber() : (Number(v) || 0);
}

/// Land a diagnostic on the gateway REGARDLESS of the Diagnostics toggle. This is
/// the ONE signal we cannot ask an owner to share by hand -- the election a hand-off
/// made, and the latency it paid -- so it BYPASSES `DaimondDiag` and the opt-in ring
/// entirely and posts straight to `/api/debug-trace`. Same wire shape as diag.js's
/// `flush` (`{v:1, device, rows:[{ts,tag,data}]}`), so the gateway handler needs no
/// change. Best-effort in every limb: it swallows every error and never blocks or
/// breaks the dispatch that called it. Ids, ages and counts only -- never content.
function postDebugTrace(rows) {
	try {
		if (!Array.isArray(rows) || !rows.length) return;
		var device = '';
		try { device = (window.DaimondIdentity && DaimondIdentity.deviceId()) || ''; } catch (e) { /* no id yet */ }
		fetch('/api/debug-trace', {
			method:      'POST',
			credentials: 'same-origin',
			headers:     { 'content-type': 'application/json', 'x-daimond-api': String(DaimondGateway.clientApi()) },
			body:        JSON.stringify({ v: 1, device: device, rows: rows }),
		}).then(function () {}, function () {});		// fire-and-forget; a down endpoint is not our problem
	} catch (e) { /* diagnostics must never break a dispatch */ }
}

/// AUTO-LAND THE ELECTION SMOKING-GUN, on EVERY nominee-set dispatch, bypassing the
/// Diagnostics toggle. Three fixes reasoned from code have failed live because the
/// iPhone's CLIENT-SIDE dispatch decision -- its nominee belief and its local presence
/// snapshot -- is invisible server-side; this makes it land on the gateway without the
/// owner navigating any UI. Fired whether the nominee is chosen OR bypassed, so both
/// the failing and the working case are captured.
///
/// The trace is the structured election object of the on-device diagnostics, emitted
/// as SHORT TAGGED ROWS rather than one JSON row: `debug_trace.rs` caps a row's `data`
/// at 400 bytes (`MAX_DATA`), and one JSON object of a 3-device election runs ~560
/// bytes and would truncate. The tagged rows are its lossless flattening and need no
/// gateway change. The object each row-set encodes is:
///   { kind:'election', ts, self, isPhone, nominatedId, nomineePresent,
///     nomineeRec:{lastSeen,servicedAt,ageMs}|null,
///     peers:[{id,lastSeen,servicedAt,ageMs,attended}],
///     decision:{reason,chosenId,chosenName},
///     refreshLanded, presumeNomWin, nowSkewNote,
///     nomineeInRoster, roster:[ids] }
function autoLogElection(presence, self, nominee, d, refreshLanded, presumeNomWin, isPhone) {
	try {
		// Only when a nominee is SET and is not this device: that is the case under
		// investigation, and the guard keeps the post off ordinary desktop turns.
		if (!nominee || nominee === self) return;
		var now  = Date.now();
		var pres = presence || {};
		var nomRec     = pres[nominee] || null;
		var nomPresent = !!nomRec;
		var rosterIds = [], nomInRoster = false;
		try {
			var reg = loadDevices();
			rosterIds   = Object.keys(reg);
			nomInRoster = rosterIds.indexOf(nominee) !== -1;
		} catch (e) { /* roster not readable */ }
		var chosenId   = (d && d.peer && d.peer.deviceId) || '';
		var chosenName = (d && d.peer && d.peer.name) || '';
		// Presence could not be confirmed for a stale-looking nominee (presumeNomWin>0):
		// the snapshot the decision read may pre-date the nominee's real beat.
		var skewNote   = (presumeNomWin > 0) ? 'nominee-unconfirmed-snapshot' : '';
		var rows = [];
		// (1) THE ONE-LINE GUN: self, phone, nominee, its presence/roster standing, the
		//     decision's reason and chosen device, and the freshness flags.
		rows.push({ ts: now, tag: 'election', data:
			'self=' + String(self || '').slice(0, 16)
			+ ' phone=' + (isPhone ? 'Y' : 'N')
			+ ' nominee=' + String(nominee).slice(0, 16)
			+ ' present=' + (nomPresent ? 'Y' : 'N')
			+ ' inRoster=' + (nomInRoster ? 'Y' : 'N')
			+ ' reason=' + String((d && d.reason) || '?')
			+ ' dispatch=' + (d && d.dispatch ? 'Y' : 'N')
			+ ' chosen=' + (chosenId ? String(chosenId).slice(0, 16) + '/' + chosenName : 'none')
			+ ' refreshLanded=' + (refreshLanded ? 'Y' : 'N')
			+ ' presumeNomWin=' + (presumeNomWin | 0)
			+ (skewNote ? ' skew=' + skewNote : '') });
		// (2) THE NOMINEE'S OWN RECORD, so a nominee-id mismatch is told from a stale beat.
		if (nomRec) {
			var nls = _msNum(nomRec.lastSeen);
			var nsv = (nomRec.servicedAt != null) ? _msNum(nomRec.servicedAt) : null;
			rows.push({ ts: now, tag: 'election nominee', data:
				'lastSeen=' + nls + ' servicedAt=' + (nsv == null ? 'n/r' : nsv) + ' ageMs=' + (now - nls) });
		} else {
			rows.push({ ts: now, tag: 'election nominee', data: 'absent-from-snapshot' });
		}
		// (3) EVERY DEVICE IN THE SNAPSHOT, one row each: beat age, servicing age, attended.
		Object.keys(pres).forEach(function (id) {
			var r = pres[id]; if (!r) return;
			var ls = _msNum(r.lastSeen);
			var sv = (r.servicedAt != null) ? _msNum(r.servicedAt) : null;
			rows.push({ ts: now, tag: 'election peer', data:
				String(id).slice(0, 16) + (id === String(self || '') ? '(self)' : '')
				+ ' lastSeen=' + ls
				+ ' servicedAt=' + (sv == null ? 'n/r' : sv)
				+ ' ageMs=' + (now - ls)
				+ ' attended=' + (r.attended ? 'Y' : 'N') });
		});
		// (4) THE ACCOUNT'S ROSTER VIEW of the nominee.
		rows.push({ ts: now, tag: 'election roster', data:
			'nomineeInRoster=' + (nomInRoster ? 'Y' : 'N')
			+ ' ids=' + rosterIds.map(function (x) { return String(x).slice(0, 16); }).join(',') });
		postDebugTrace(rows);
	} catch (e) { /* best-effort: never break a dispatch */ }
}

/// AUTO-LAND THE HAND-OFF LATENCY when the answer for a dispatched turn finally merges
/// on THIS (the originating) device, so the delay is quantified and the advertised
/// target is proved against the device that really ran it. Reads the up-front election
/// trace kept for the turn (advertised target, and whether/when `stampDispatchHolders`
/// later corrected the holder), and the live lease holder as a fallback for the real
/// runner. Best-effort. Ids and counts only.
export function autoLogHandoffLatency(turnId, dispatchTs) {
	try {
		var now = Date.now();
		var et  = _electionTrace[String(turnId)] || null;
		var advertised = et ? et.advertisedId   : '';
		var advName    = et ? et.advertisedName : '';
		var corrected  = et ? et.correctedHolder : '';
		var corrAfter  = et ? et.correctedAfterMs : -1;
		var holder = '';
		try { holder = (window.DaimondLease && DaimondLease.holder) ? String(DaimondLease.holder(turnId) || '') : ''; }
		catch (e) { /* lease view gone once released */ }
		var actualRunner = corrected || holder || '';
		var dt = _msNum(dispatchTs);
		postDebugTrace([{ ts: now, tag: 'handoff_latency', data:
			'turn=' + String(turnId)
			+ ' dispatchTs=' + dt
			+ ' answerMergedTs=' + now
			+ ' latencyMs=' + (now - dt)
			+ ' advertised=' + (advertised ? String(advertised).slice(0, 16) + '/' + advName : 'generic')
			+ ' actualRunner=' + (actualRunner ? String(actualRunner).slice(0, 16) : 'unknown')
			+ ' holderCorrected=' + (corrAfter >= 0 ? 'Y' : 'N')
			+ ' correctedAfterMs=' + (corrAfter >= 0 ? corrAfter : -1) }]);
	} catch (e) { /* best-effort */ }
	try { delete _electionTrace[String(turnId)]; } catch (e) { /* map stays bounded anyway */ }
}

/// The device a dispatch was elected to, as the first entry of the turn's
/// `triedDevices` (R4b). The advertised label can be empty -- no nominee names
/// nobody -- or name a nominee the election passed over, and the backstop seeds what
/// it has tried from that label alone, so it re-handed the turn to the very desktop
/// that had just failed to collect it and ran it here only at the second backstop,
/// about 190 s after the send. Recorded, and not advertised: the tile's words stay
/// as they were.
function electedTried(d) {
	var id = (window.DaimondPeer && DaimondPeer.peerIdOf) ? DaimondPeer.peerIdOf(d && d.peer) : '';
	return id ? [id] : [];
}

/// Answer, in the transcript, a hand-off the door turned away before it marked the turn
/// (R53-U8, 2026-09-25; SEND-UNHANDED). Called only by `handOffTurn`, the one entry,
/// so no caller reads a refusal its own way.
///
/// - A person's pause is said in their words, as the local run would say it, where
///   nothing else answers for the turn (as before).
/// - Every other refusal leaves a durable "not run" row on the turn: an answer row,
///   interrupted, carrying `notRun` (`isNotRunRow`), tagged `why: 'runner'` in a chat and
///   `why: 'notrun'` in a Diamond (the tag each old build routes; see there), drawn as
///   the turn's quiet tile with a Retry wired to
///   `retryTurn` (`markInterrupted`). It syncs like any row, so every device shows it.
///   Where the turn already has a row of its own past its prompt (a step-away from a
///   run under way here, whose interruption is its own answer) nothing is added; a
///   parked turn's placeholder does not count, since a refused re-run is still not run.
///   A second refusal of the same turn refreshes its row rather than adding one. Its mid
///   is the turn's (`tid + '-nr'`), so two devices, or two tabs rebuilding it (F4), that each
///   write it before either syncs merge into ONE row, and `have` finds the synced copy
///   (review LOW-3).
export function answerUnhanded(chat, turnId, text, r) {
	try {
		var tid = String(turnId || '');
		if (!chat || !tid) return;
		var msgs = chat.messages || (chat.messages = []);
		var paused = !!(r && r.paused);
		var why = String((r && r.why) || 'the hand-off door gave no reason');
		var have = null;
		for (var i = msgs.length - 1; i >= 0; i--) {
			var m = msgs[i];
			if (!m || String(m.iturn || '') !== tid || m.role === 'user') continue;
			if (paused) return;
			if (isNotRunRow(m)) { have = m; continue; }
			if (m.why === 'dispatched') continue;
			return;
		}
		if (paused) {
			msgs.push(touchMsg({ role: 'note_log', content: DaimondModels.pauseError(r.node).message,
				mid: newMid(), iturn: tid, ts: Date.now() }));
			diag('dispatch unhanded', 'turn=' + tid + ' paused at ' + r.node);
		} else if (have) {
			have.notRun = notRunRecord(why, r);
			touchMsg(have);
			diag('dispatch not run', 'turn=' + tid + ' again: ' + why);
		} else {
			// Tagged so an old build's Retry routes it as one turn (`isNotRunRow`): a chat's as a
			// lost turn, a Diamond's as "not run", the only tag the live build routes for one.
			msgs.push(touchMsg({ role: 'assistant', content: '', interrupted: true, why: chat.diamondId ? 'notrun' : 'runner',
				iturn: tid, itext: String(text || ''), mid: tid + '-nr', ts: Date.now(),
				notRun: notRunRecord(why, r) }));
			diag('dispatch not run', 'turn=' + tid + ' ' + why);
		}
		touchChat(chat);
		persistChats();
		if (ownsChat(chat)) renderHistory(chat.messages);
	} catch (e) { /* the prompt stands in the transcript either way */ }
}

/// A "not run" row's `notRun`: the diagnostic words `why`, and the cause the tile names
/// (`r.nr`, a `notRunCause`), kept flat so a row synced to an older page still reads.
function notRunRecord(why, r) {
	var o = { why: why, unable: !!(r && r.unable), ts: Date.now() };
	var nr = r && r.nr;
	if (nr && nr.cause) {
		o.cause = nr.cause;
		if (nr.to) o.to = nr.to;
		if (nr.name) o.name = nr.name;
		if (nr.said) o.said = nr.said;
	}
	return o;
}

/// End a send whose pressed runner cannot take it as the "not run" row with Retry on
/// this device (`answerUnhanded`): the composer gives up the words, the prompt is
/// written under the turn id, and nothing runs anywhere. True, so no local run follows.
function endSendNotRun(chat, text, words, mid, app, why, nr) {
	var nmid = mid || newMid();
	giveUpSent(chat, words === undefined ? text : words);
	commitRatings(chat.id, { });
	var nts = Date.now();
	if (ownsChat(chat)) {
		try { appendUserMessage(text, nts, undefined, undefined, !!app); } catch (e) { /* the record below is the truth */ }
	}
	pushUserRecord(chat, touchMsg({ role: 'user', content: text, mid: nmid, iturn: nmid, ts: nts,
		effort: turnEffortOf(chat) }), !app);
	answerUnhanded(chat, nmid, text, { ok: false, why: why, nr: nr });
	return true;
}

/// At send-time: hand this turn to a peer instead of running it here, when the
/// pure policy says so. On a phone with an awake peer that is EVERY turn (the
/// answer syncs back); on desktop only a long/agentic turn. Answers whether it
/// dispatched; false falls through to the ordinary local run. Guarded, so any
/// hiccup runs locally -- the safe default. `app` marks a prompt the app wrote in the
/// person's place (a Continue's nudge), which takes no note and is stored as the app's.
/// `drawn` is the runner the switch drew at the press (`seatDrawnRunner`), where the press
/// came before this call; read here, before the first wait, where it did not. `how.pendingOnly`
/// rides the errand for a mail trigger's turn, which reports on the Pending panel alone (§16).
export async function maybeAutoDispatch(chat, text, words, mid, app, drawn, how) {
	try {
		// A DAIMON DISPATCHES TOO. The election/lease/hand-off is proven for chats and
		// is switched on for daimons here: the runner services the turn through
		// `steer_crystal` (peerRunErrandDeps.runTurn branches on the errand's diamondId),
		// which is per-call fenced to the Diamond's own directory. The `diamondId` rides
		// the errand so the runner steers the crystal rather than the chat engine. Money-
		// safety is unchanged: the take-if-vacant lease is still the sole single-runner
		// arbiter, and the transcript `iturn` finished-guard stops a re-collect re-running.
		if (!chat) return false;
		// WHAT THE SWITCH DREW AT THE PRESS, taken before the presence read below can redraw
		// it. A switch that cannot be read drew no runner.
		var shown = drawn;
		if (shown === undefined) { try { shown = seatDrawnRunner(chat); } catch (e) { shown = ''; } }
		shown = String(shown || '');
		// HELD BY A PERSON, IT IS NOT HANDED ANYWHERE (R2 QA, F2). Asked before the
		// election, which commits the turn to a hand-off before `dispatchToPeer` is
		// reached: false here, and the local run refuses it in the person's words.
		if (turnHold(chat)) return false;
		if (typeof navigator !== 'undefined' && navigator.onLine === false) return false;
		if (!window.DaimondPeer || !DaimondPeer.autoDispatchDecision) return false;
		var self     = selfDeviceId();
		var nominee  = (typeof nominatedDeviceId === 'function') ? nominatedDeviceId() : '';
		var presence = (window.DaimondPresence && DaimondPresence.snapshot()) || {};
		// Presence freshness governs the dispatch, so make it current. If a runner is
		// NOMINATED but its BEAT looks stale/absent in this snapshot -- the case right
		// after a hard refresh, before presence has re-synced -- do a BOUNDED, awaited
		// refresh and re-snapshot before deciding, so a set-and-alive designated runner
		// is not misjudged offline. Only that case waits: a nominee already beating, or
		// no nominee, keeps the fire-and-forget nudge and pays nothing. The race caps the
		// wait so a slow gateway never holds the send.
		//
		// The gate is the nominee's BEAT (nominationStandDown / lastSeen), matching what
		// autoDispatchDecision now seats the nominee on -- and what the CLAIM arbitration
		// uses. Gating on recGenuine (serviced_at) instead (seq 225) made iOS await for a
		// signal the decision no longer needs, and a beating-but-serviced-stale nominee
		// was then dropped for a fresher peer at dispatch while it won the claim -- the
		// mismatch the owner hit (argonaut is the runner, gilgamesh was labelled). A
		// beating nominee is now chosen DIRECTLY; a nominee that never services is
		// recovered by the undeliverable→local backstop (seq 222).
		var nomStale = !!nominee && nominee !== self && DaimondPeer.nominationStandDown
			&& !DaimondPeer.nominationStandDown(nominee, self, presence, Date.now(), DaimondPeer.DISPATCH_FRESH_MS);
		var tSend = Date.now();		// turn-send, the origin of the hand-off latency breakdown
		// Did the awaited nominee refresh actually LAND before the send? When it did not
		// (a cold-foreground GET slower than the cap), a stale-looking nominee beat is
		// unconfirmed, not a proof of offline -- so the decision presumes the always-on
		// runner live over `NOMINEE_TRUST_MS` rather than misrouting to a fresher peer.
		var refreshLanded = false;
		var derived = !!(window.DaimondSync && DaimondSync.presenceDerived && DaimondSync.presenceDerived());
		if (derived && DaimondSync.refreshPresence) {
			// Under the derived truth every send reads, and nothing is presumed: a read
			// that did not land keeps the turn Here (HT2 M1).
			var read = await sendPresenceRead();
			if (!read) {
				// THE PERSON PRESSED THE RUNNER AND THE READ DID NOT LAND (QA-HT-B F1, rulings §1
				// l.9, l.17). A turn the switch sends to a runner never runs elsewhere silently:
				// it ends as the "not run" row with Retry on this device, the same terminal as a
				// refusal at the door (`answerUnhanded`), and the election is logged. A chat the
				// switch showed no runner for (or pinned Here) runs here, as before.
				var pressed = !!shown && !chatSeatHere(chat);
				diag('handoff send read', 'presence read did not land in ' + PRESENCE_READ_CAP_MS + 'ms; '
					+ (pressed ? 'not run (runner ' + shown + ' pressed)' : 'Here'));
				try { autoLogElection(presence, self, nominee, { dispatch: false, reason: pressed ? 'read-missed-notrun' : 'read-missed-here' },
					false, 0, isPhoneViewport()); } catch (e) { /* best-effort */ }
				try { renderSeatSwitch(); } catch (e) { /* the next beat redraws it */ }
				if (!pressed || turnHold(chat)) return false;
				if (how && how.prep) how.prep();		// a retry's turn is retracted at the commit
				return endSendNotRun(chat, text, words, mid, app, 'presence read did not land in '
					+ PRESENCE_READ_CAP_MS + 'ms; runner ' + shown + ' unconfirmed', notRunCause('unchecked', '', shown));
			}
			presence = read;
			refreshLanded = true;
		} else if (window.DaimondSync && DaimondSync.refreshPresence) {
			if (nomStale) {
				// (b) THE NOMINEE PRESENCE-REFRESH AWAIT. Capped, because it blocks the
				// send -- but the cap is generous (NOMINEE_REFRESH_CAP_MS): a cold iOS
				// foreground presence GET does not complete in ~900ms, so the old cap let
				// the timeout win and the send decided on the STILL-stale snapshot, aging
				// a live nominee (argonaut) past the 90s gate and handing the turn to the
				// freshest peer (gilgamesh). The refresh WINS the race the instant it
				// returns, so a warm tab pays ~100ms and only a cold open waits -- and
				// that cold open is exactly the case that was misrouting. `refreshLanded`
				// distinguishes "landed, nominee genuinely stale" (fall through) from
				// "timed out, nominee unconfirmed" (presume live, below).
				var tRefresh = Date.now();
				try {
					await Promise.race([
						Promise.resolve(DaimondSync.refreshPresence()).then(function () { refreshLanded = true; }),
						new Promise(function (r) { setTimeout(r, NOMINEE_REFRESH_CAP_MS); }),
					]);
				} catch (e) { /* the snapshot we have stands */ }
				presence = (window.DaimondPresence && DaimondPresence.snapshot()) || {};
				diag('handoff refresh await', 'nominee ' + String(nominee).slice(0, 8)
					+ ' stale; blocked ' + (Date.now() - tRefresh) + 'ms; landed=' + refreshLanded);
			} else {
				try { DaimondSync.refreshPresence(); } catch (e) { /* the local snapshot stands */ }
			}
		}
		// Presence could not be CONFIRMED (a nominee that looked stale and whose refresh
		// did not land): trust a set nominee last known within NOMINEE_TRUST_MS over the
		// tight 90s beat gate, so a live always-on runner is never bypassed for a peer on
		// an unconfirmed snapshot. Zero in every confirmed case, so autoDispatchDecision
		// keeps its normal 90s nominee gate.
		var presumeNomWin = (nomStale && !refreshLanded) ? NOMINEE_TRUST_MS : 0;
			presence = presenceWithLeaseBusy(turnPresence(presence), chat);
			// ROUTING READS LIVE PRESENCE, NOT THE STORED DEVICE LIST (owner redesign
			// 2026-09-09). The star an older account carries points at the argonaut's DEAD
			// pre-re-mint id; `handoffTarget` never seats that raw id unless it is ITSELF
			// live in presence, and otherwise matches the star's LABEL against whoever
			// carries it in live presence -- so a ghost id is ignored and the machine that
			// is HERE NOW is seated. `reconcileRoster` is kept for roster HYGIENE (it moves
			// the star onto a live successor id and sweeps dead lines for the Devices panel),
			// but routing no longer DEPENDS on it: the label resolution below is the
			// authority and is ghost-proof on its own. Money-safe: the lease CAS is still
			// the sole single-runner arbiter; this only changes WHICH live device is seated.
			try { reconcileRoster(); } catch (e) { /* routing does not depend on this */ }
			nominee = (typeof nominatedDeviceId === 'function') ? nominatedDeviceId() : nominee;
			var d = DaimondPeer.autoDispatchDecision(chat, presence, {
			selfId:        self,
			isPhone:       isPhoneViewport(),
			toolsEnabled:  chatToolsEnabled(chat),
			// The star as a LABEL, resolved against live presence each dispatch, for the case
			// where the stored star id is not beating. Seated only when exactly ONE live
			// desktop carries the label (handoffTarget a'), so a name two machines share
			// never decides which of them runs and bills the turn.
			preferredLabel: preferredWorkerLabel(),
			// The build this device knows is current, so the election can PREFER a
			// current-build peer over a superseded one (a warning/preference, never a
			// hard exclusion -- see freshestGenuinePeer). The mixed-build hand-off
			// failure, guarded: a stale peer is no longer silently trusted.
			currentBuild:  fleetCurrentBuild(),
			// The account's nominated always-on runner: when it is fresh it takes
			// every turn (autoDispatchDecision's `nominee` branch), above the
			// mobile / agentic / quick-local rules.
			nominatedId:   nominee,
			// The step-away posture makes this device — a laptop as much as a phone —
			// route its turns to an awake peer so they run there and survive it being
			// closed. Off by silence, so a machine that never turned it on keeps
			// today's behaviour: a desktop runs its own quick turns, a phone routes
			// on its own `isPhone` rule. The pure decision reads this as
			// `globalDefault` and honours a per-chat opt-out ahead of it.
			globalDefault: handoffWhenAway(),
			// A dispatch uses a TIGHTER freshness than the display: a peer last seen
			// longer ago than this is treated as gone, so a turn is not handed to a
			// device that may have died since its last beat. Recovery-on-return is
			// the safety net for the residual race; this keeps most turns off it.
			freshWindowMs: DaimondPeer.DISPATCH_FRESH_MS,
			// When presence could not be confirmed, presume a set nominee live over
			// this wide window rather than misroute to a fresher peer (see above).
			presumeNomineeWindowMs: presumeNomWin,
			// The device already running this chat: a busy machine is still seated for
			// it, and the follow-up queues there behind the running turn (H1, O3).
			queueOn:       chatRunningOn(chat),
			// The person's switch: Here pins the chat; otherwise only the runner the
			// switch names may take the turn (D-20261009-23).
			toggle:        chatSeatHere(chat) ? false : null,
			// The chat's folder is rooted here: only a runner holding one is offered (F4c).
			needFolder:    chatNeedsFolder(chat),
			runnerOnly:    true,
			// The provider the turn runs on, as the errand will carry it (`electProvider`).
			provider:      electProvider(chat),
			sources:       electSources(chat),
		}, Date.now());
		// THE SMOKING GUN: exactly what the election saw and chose. This is the
		// line that says WHY iOS picks the device it picks.
		diag('dispatch election', electionTrace(presence, self, nominee, d, DaimondPeer.DISPATCH_FRESH_MS));
		// AUTO-LAND that smoking-gun on the gateway, bypassing the Diagnostics toggle,
		// on EVERY nominee-set dispatch -- chosen or bypassed, dispatching or not -- so
		// the client-side election a live iPhone made is diagnosable server-side without
		// the owner sharing anything by hand. Before the `!d.dispatch` return, so the
		// no-dispatch case is captured too. Guarded internally to nominee-set turns.
		try { autoLogElection(presence, self, nominee, d, refreshLanded, presumeNomWin, isPhoneViewport()); }
		catch (e) { /* best-effort */ }
		if (!d.dispatch) {
			// THE PERSON PRESSED THE RUNNER AND IT WAS GONE BY THE SEND (QA-SUHT-B F5, rulings
			// l.9, l.17): the same terminal as a read that did not land, the "not run" row with
			// Retry here. Only a switch that drew Here at the press, or drew no runner, runs the
			// turn here (`shown`, killrunner).
			try { renderSeatSwitch(); } catch (e) { /* the next beat redraws it */ }
			if (!shown || chatSeatHere(chat) || turnHold(chat)) return false;
			if (how && how.prep) how.prep();
			// A runner no longer seen is said to have gone; any other decline keeps the plain words.
			var gone = d.reason === 'no-genuine-peer' || d.reason === 'no-runner';
			return endSendNotRun(chat, text, words, mid, app, 'runner ' + shown
				+ ' was pressed and the election declined it (' + String(d.reason || 'no reason') + ')',
				gone ? notRunCause('gone', '', shown) : null);
		}
		// ASKED AGAIN AT THE COMMIT (R53-U8, 2026-09-25). The question at the top was asked
		// before the presence refresh, which can hold the send for NOMINEE_REFRESH_CAP_MS,
		// and a pause that landed in that wait (a pull, another tab's press) was read only by
		// `dispatchToPeer` -- after the prompt below was written and the composer cleared. It
		// refused with no placeholder, this caller did not look, and the backstop found no
		// placeholder to recover: a turn neither run, nor handed on, nor refused in words.
		// Asked here, in the same synchronous run as `dispatchToPeer`'s own question, so the
		// two cannot disagree; false, and the local run refuses it in the person's words.
		if (turnHold(chat)) return false;
		// A retry's turn leaves the thread here, before the hand-off builds it (`retryDiamond`).
		if (how && how.prep) how.prep();
		// Prepared exactly as the explicit path, so the parcel push inside
		// dispatchToPeer carries the prompt (§4.1). The composer gives up the words
		// this press sent and nothing typed since (`giveUpSent`), and gives them up
		// from this conversation's box even when another is on screen now.
		giveUpSent(chat, words === undefined ? text : words);
		var umid = mid || newMid();	// a retry's replacing turn keeps the id the ledger was told
		_handoffStart[umid] = tSend;		// origin for the answer-arrival timing
		// THE IN-FLIGHT TILE MUST ADVERTISE THE DEVICE THE CLAIM ROUTES TO, not the
		// send-time freshest-peer GUESS (`d.peer`). When a nominee is SET, that is the
		// nominee: `autoDispatchDecision`'s nominee branch dispatches to it and the lease
		// claim lands on it, but when the phone's snapshot shows the nominee stale the
		// decision falls to the freshest peer, so `d.peer` reads gilgamesh while argonaut
		// actually runs -- the tile then advertised the wrong device until a delayed
		// correction (owner 2026-09-07). With NO nominee set, advertise NOTHING specific:
		// the generic seq-217 label ("Sent to your other devices"), never a guessed
		// device. `stampDispatchHolders` still corrects the tile to the real lease holder
		// once the claim is known, and now agrees with this up-front label.
		var advId   = (nominee && nominee !== self) ? nominee : '';
		var advName = advId ? deviceLabelFor(advId) : '';
		// Keep the election trace for this turn, so the answer-arrival auto-log can report
		// the advertised target against the device that really claimed it.
		_electionTrace[umid] = {
			dispatchTs:       tSend,
			advertisedId:     advId,
			advertisedName:   advName,
			correctedHolder:  '',
			correctedAfterMs: -1,
		};
		// TRAINING WHEELS — the debug feed's `handoff`, the ELECTION half: what
		// this device decided at send time, which the lease events then either
		// bear out or contradict. Ids only, short.
		var seatRec = (presence || {})[String(DaimondPeer.peerIdOf(d && d.peer))] || null;
		dsEvent('handoff', {
			act:  'elect',
			turn: String(umid).slice(0, 24),
			self: String(self || '').slice(0, 12),
			to:   String(advId || '').slice(0, 12),
			// THE TARGET'S ID, through `DaimondPeer.peerIdOf`. A `handoffTarget`
			// record names the device in `deviceId`, never `id`, so `d.peer.id ||
			// d.peer` fell through to the object itself and every elected dispatch
			// reported `peer:"[object Obje"` -- the one field this row exists for.
			peer:     String(DaimondPeer.peerIdOf(d && d.peer)).slice(0, 12),
			peerName: String(DaimondPeer.peerLabelOf(d && d.peer)).slice(0, 24),
			why:  String((d && d.reason) || '').slice(0, 24),
			// THE SEAT'S LOAD AT THE MOMENT IT WAS CHOSEN (H1, C7): busy, its queue depth and
			// the age of the beat that said so, and the busy peers passed over for it. 28% of
			// elections seated a device reporting busy, and this row could not show it.
			busy:     !!(seatRec && seatRec.busy > 0),
			queue:    seatRec ? (seatRec.busy | 0) : -1,
			beat:     seatRec ? Math.round((Date.now() - (+seatRec.lastSeen || 0)) / 1000) : -1,
			passed:   ((d && d.passed) || []).map(function (x) { return String(x.deviceId).slice(0, 12) + ':' + (x.busy | 0); }).join(',').slice(0, 64),
		});
		// THE NEXT MESSAGE COMMITS THE RATINGS MADE SO FAR, as `runTurn` does, so a draft still
		// pending is a record before the note for this message is composed, and sits before it.
		commitRatings(chat.id, { });
		var uts = Date.now();
		// Drawn only into its own thread: the refresh's wait may have taken the person to
		// another conversation, whose thread this prompt is not.
		if (ownsChat(chat)) {
			try { appendUserMessage(text, uts, undefined, undefined, !!app); } catch (e) { /* the record below is the truth */ }
		}
		// STAMPED: the runner writes this message too (from the seed or the errand), and
		// those copies carry no stamp, so the copy this device wrote -- with its `iturn`
		// and its `ts` -- is the one every device keeps (`msgJoin`).
		// The Effort it is sent with is on it too, so the runner and a re-dispatch read the same one.
		pushUserRecord(chat, touchMsg({ role: 'user', content: text, mid: umid, iturn: umid, ts: uts,
			effort: turnEffortOf(chat) }), !app);
		touchChat(chat); persistChats();
		// SHOW THE HAND-OFF THE INSTANT IT IS DECIDED, from the DURABLE record.
		// `dispatchToPeer` now MARKS the turn dispatched FIRST -- before it seals or
		// posts -- so the durable `why:'dispatched'` placeholder, and its identical
		// hand-off tile through `drawHistoryMessage`, is on screen the moment the seal
		// completes (local crypto, not the network round trip). No SYNTHETIC DOM-only
		// tile is drawn here: that was the interim representation a store-driven
		// rebuild wiped, which -- with no durable row behind it on a refused post --
		// left the user an empty turn (D-20260918-27). A refused or undeliverable post
		// is handled INSIDE `dispatchToPeer`: it stamps the durable placeholder and
		// runs the turn locally (money-safe via the lease), so there is no DOM-only
		// `appendError` to be wiped and no dead turn to recover from nothing.
		handOffTurn(chat, umid, text, Array.isArray(chat.holds) ? chat.holds : [],
			{ toId: advId, toName: advName, runTo: DaimondPeer.peerIdOf(d.peer), t0: tSend, diamondId: String(chat.diamondId || ''),
				tried: electedTried(d), pendingOnly: !!(how && how.pendingOnly) }
		);	// a refusal is answered by the entry itself: not run, with Retry
		// Arm the last-resort recovery backstop: if no peer claims this within ~one
		// freshness window, run it here rather than let the spinner hang to the
		// 15-min deadline (Fix B). Money-safe via the take-if-vacant lease. A turn
		// seated on a PRESUMED-live nominee (unconfirmed snapshot) gets a TIGHT
		// backstop, so a nominee that was in fact asleep recovers in seconds.
		try {
			var presumed = d.reason === 'nominee-presumed';
			scheduleDispatchFallback(chat.id, umid, presumed ? PRESUMED_FALLBACK_MS : undefined);
		} catch (e) { /* recovery-on-return still nets it */ }
		return true;
	} catch (e) { return false; }		// any hiccup: run locally
}

/// The in-flight turn of a generating chat, as `{ turnId, text }`, or null.
///
/// A turn's prompt is the last user message pushed before it began (runTurn:
/// mid === the turn id), so for a chat that is generating right now that message
/// IS the running turn. The turn id and the prompt are all a hand-off needs; the
/// transcript and scope ride the parcel, not the errand.
function inflightTurnOf(chat) {
	var msgs = (chat && chat.messages) || [];
	for (var i = msgs.length - 1; i >= 0; i--) {
		if (msgs[i].role === 'user') return { turnId: String(msgs[i].mid), text: msgs[i].content || '' };
	}
	return null;
}

/// Hand any turn still running on THIS device to an awake peer, because the device
/// is being stepped away from — the tab is unloading, the lid is closing. Gated on
/// the step-away posture (off by silence), so a machine that never asked for this
/// keeps its interrupted turn and its Continue button.
///
/// It REUSES the ordinary dispatch hand-off (`dispatchToPeer`) and adds no rule of
/// its own: the pure decision picks the freshest peer (backgrounding + a turn in
/// flight is the §4.1 case), the lease is the single-runner arbiter, and a
/// dispatch that does not land in the page's dying moments is caught by
/// recovery-on-return — `recoverDecision` re-runs a dispatched turn that no peer
/// took, so the turn is never lost either way. Called from `pagehide`, where the
/// local turn dies with the page, so there is no window in which both run.
export function handoffInFlightOnStepAway() {
	try {
		if (!handoffWhenAway()) return;
		if (typeof navigator !== 'undefined' && navigator.onLine === false) return;
		if (!window.DaimondPeer || !DaimondPeer.autoDispatchDecision || !DaimondPeer.DISPATCH_FRESH_MS) return;
		var presence = (window.DaimondPresence && DaimondPresence.snapshot()) || {};
		var self = selfDeviceId(), now = Date.now();
		pg.chats.forEach(function (chat) {
			// A daimon turn hands off on step-away too: `runSteer` sets `_generating` and
		// its user message carries the `mid` `inflightTurnOf` resolves, so the same
		// dispatch reaches it. The dispatch names the chat's `diamondId` so the runner
		// steers the crystal.
		if (!chat || !chat._generating) return;
			var turn = inflightTurnOf(chat);
			if (!turn) return;
			// PAST THE WINDOW, NOT HANDED ON (E-R1). Every collector refuses a turn older
			// than the window from its birth (`turnAgeVerdict`), so a long local turn -- or
			// a continuation run under an old turn's id -- keeps its Continue here rather
			// than going out as an errand nobody may start.
			if (!DaimondPeer.turnInWindow || !DaimondPeer.turnInWindow([turn.turnId], [], now)) return;
			// The posture gate above is the "should we hand off at all" decision;
			// the pure call only picks the freshest peer and confirms one is awake
			// (no fresh peer -> keep it here, to be recovered on return). This IS the
			// §4.1 backgrounding-with-a-turn-in-flight case, and a per-chat opt-out
			// still beats it inside the pure decision.
				presence = turnPresence(presence);
				var d = DaimondPeer.autoDispatchDecision(chat, presence, {
				selfId:        self,
				backgrounding: true,
				turnInFlight:  true,
				// The star as a LABEL, ghost-proof (see the send-time site).
				preferredLabel: preferredWorkerLabel(),
				// See the send-time site: prefer a current-build peer, never exclude a
				// stale one. A step-away hand-off must still land somewhere.
				currentBuild:  fleetCurrentBuild(),
				// THE NOMINATED RUNNER TAKES A STEP-AWAY HAND-OFF TOO. Without this the
				// decision skipped its nominee branch and handed the turn to the
				// FRESHEST peer instead — so a turn in flight when a device was closed
				// ran on whatever beat most recently (gilgamesh) rather than on the
				// always-on runner the account named (argonaut), which is exactly what
				// the nomination is for. The send-time path already passes this; the
				// step-away path was the one that did not, so the two disagreed on
				// where a turn goes.
				nominatedId:   nominatedDeviceId(),
				freshWindowMs: DaimondPeer.DISPATCH_FRESH_MS,
				provider:      electProvider(chat),	// as the send-time site
				sources:       electSources(chat),
			}, now);
			diag('dispatch election', 'step-away ' + electionTrace(presence, self, nominatedDeviceId(), d, DaimondPeer.DISPATCH_FRESH_MS));
			if (!d.dispatch) return;
			// Best-effort: the page is going, so this is not awaited. `markTurnDispatched`
			// inside runs first and is synchronous, so recovery-on-return sees the turn
			// as dispatched even if the push/post do not finish — and a dispatched turn
			// no peer ran is reclaimable.
			try { handOffTurn(chat, turn.turnId, turn.text, Array.isArray(chat.holds) ? chat.holds : [],
				{ diamondId: String(chat.diamondId || ''), tried: electedTried(d), runTo: DaimondPeer.peerIdOf(d.peer), stepAway: true }); }
			catch (e) { /* recovery-on-return is the net */ }
		});
	} catch (e) { /* the page is going; nothing here may throw into unload */ }
}

/// The presence beat: while this tab is AWAKE and visible, write a heartbeat into
/// the parcel every ~45 s so the phone knows this device is awake and can name it
/// ("waiting for argonaut"). A missed beat is a stale beat, which is safe (the
/// deadline and lease catch a peer that actually slept).
var _presenceTimer = null;
// ══════════════════════════════════════════════════════════════
// WHAT THIS DEVICE CAN DO, AND WHAT IT LAST SAW OTHERS DO
// --------------------------------------------------------------
// Two live facts ride the beat, and a third thing is remembered locally: the last
// time each device said either of them. The remembered half is what lets a refusal
// NAME argonaut while argonaut is asleep -- "Needs argonaut awake; it holds the
// folder and the dev script" rather than "no device can do this" -- and it is kept
// OFF the synced parcel on purpose. A hand plugged in and a folder grant withdrawn
// are live per-device changes; stamping them onto the shared device roster would
// bump `seen`, and a bumped `seen` pushes the whole parcel.
// ══════════════════════════════════════════════════════════════

var PLACE_SEEN_KEY = 'daimond-place-seen';	// id -> { name, at, hand, folder, mobile }
var PLACE_SEEN_MAX = 24;					// bounded: a roster, not a log

/// Does this device hold the REAL, mounted workspace folder -- the machine's own
/// files, complete by construction -- rather than a browser replica?
export function selfHoldsFolder() {
	try { return !!(Files && Files.folder && Files.folder()); } catch (e) { return false; }
}

/// Can this device reach a machine hand at all?
///
/// The extension announcing itself on this page, or a link already open. NOT
/// `DaimondHand.status()`, which OPENS the link -- and opening it is what puts the
/// approval window on somebody's screen, so a presence beat must never do it.
/// The real folder is required beside it because `run` fences every command against
/// the granted folder and refuses outright without one, so a hand with no folder
/// under it cannot run anything and saying otherwise would seat a publish on a
/// machine that must then refuse it.
export function selfHoldsHand() {
	if (!selfHoldsFolder()) return false;
	try { if (window.DaimondHand && DaimondHand.hasHand && DaimondHand.hasHand()) return true; } catch (e) { /* fall through */ }
	try { return !!document.documentElement.dataset.daimondHands; } catch (e) { return false; }
}

/// Fold the live beats into the remembered roster: for each device that SAID
/// either field, what it said and when. Absence is never written -- a beat that
/// could not say leaves the last answer standing, which is the whole point.
function notePlaceSeen() {
	var snap = (window.DaimondPresence && DaimondPresence.snapshot()) || {};
	var kept = readJson(PLACE_SEEN_KEY, {});
	if (!kept || typeof kept !== 'object') kept = {};
	var now = Date.now(), moved = false;
	Object.keys(snap).forEach(function (id) {
		var rec = snap[id];
		if (!rec) return;
		var hasHand = typeof rec.hand === 'boolean';
		var hasFold = typeof rec.folder === 'boolean';
		if (!hasHand && !hasFold) return;
		var was = kept[id] || {};
		var line = { name: String(rec.name || was.name || ''), at: now,
			hand: hasHand ? rec.hand : was.hand,
			folder: hasFold ? rec.folder : was.folder };
		if (typeof rec.mobile === 'boolean') line.mobile = rec.mobile;
		else if (typeof was.mobile === 'boolean') line.mobile = was.mobile;
		if (JSON.stringify(was) !== JSON.stringify(line)) { kept[id] = line; moved = true; }
	});
	if (!moved) return;
	// Bounded by recency, so a fleet that churns device ids cannot grow this without
	// end: the oldest lines are the least useful sentence to offer anybody.
	var ids = Object.keys(kept).sort(function (a, b) { return (kept[b].at | 0) - (kept[a].at | 0); });
	if (ids.length > PLACE_SEEN_MAX) {
		var trim = {};
		ids.slice(0, PLACE_SEEN_MAX).forEach(function (id) { trim[id] = kept[id]; });
		kept = trim;
	}
	try { localStorage.setItem(PLACE_SEEN_KEY, JSON.stringify(kept)); } catch (e) { /* private window */ }
}

/// The roster the placement names a sleeping machine from: what each device last
/// said about its hand and its folder, with a label to say it by.
export function placeRoster() {
	var kept = readJson(PLACE_SEEN_KEY, {});
	if (!kept || typeof kept !== 'object') kept = {};
	var out = {};
	Object.keys(kept).forEach(function (id) {
		var r = kept[id] || {};
		out[id] = { name: deviceLabelFor(id) || r.name || '', lastSeen: r.at | 0,
			hand: r.hand, folder: r.folder, mobile: r.mobile };
	});
	return out;
}

/// The options a placement is taken with: the seat switch's, plus the remembered
/// roster and this device's own label. ONE place, so a compile, a publish and a
/// turn cannot be decided against three different views of the fleet.
export function placeOpts() {
	var o = seatOpts();
	o.roster   = placeRoster();
	o.selfName = deviceLabelFor(selfDeviceId()) || '';
	// What the open chat runs on (`seatOpts` sets it, `electProvider`): a native runner
	// takes a credits chat's work only (peer.js recEngineOk, R3c4c).
	return o;
}

/// This tab's posture now, as a beat states it, or null when it states nothing (a
/// hidden phone, no identity yet). `args` is `beatPresence`'s argument list.
function postureNow() {
	try {
		// A hidden PHONE tab is genuinely suspended, so it must not claim to be
		// awake. A hidden DESKTOP tab (another window has focus) is still running
		// and is exactly the persistent peer a hand-off targets -- so it keeps
		// beating while it is open, unlocked and online, even in the background.
		// Gating a desktop on visibility is what made argonaut only count as a peer
		// while its tab was foregrounded, defeating "hand off while I work elsewhere".
		if (typeof document !== 'undefined' && document.visibilityState !== 'visible'
			&& isPhoneViewport()) return null;
		if (!window.DaimondPresence || !DaimondPresence.beat) return null;
		var id = selfDeviceId();
		if (!id) return null;
		// Broadcast THIS device's own label -- the machine name in the devices list
		// ("Argonaut Chrome on Linux") -- NOT the account display name. Every device
		// of one account shares that name ("hoogs"), so beating it leaves the hand-off
		// UI unable to say WHICH machine is running the turn. Falls back to the auto
		// browser/OS name, then the account name.
		var name = '';
		try {
			var _reg = loadDevices();
			var _me  = _reg && _reg[deviceId()];
			name = (_me && (_me.label || _me.name)) || deviceSelfName(id)
				|| (window.DaimondIdentity && DaimondIdentity.displayName && DaimondIdentity.displayName()) || '';
		} catch (e) { name = ''; }
		// Carry the attention signal on the beat, so an attended device is routable
		// for a live consent. The optimistic local update carries it directly; the
		// gateway path (beatPresence) forwards it too, so once the gateway relays
		// `attended`/`attended_at` a runner can route to an attended peer live.
		var att = isAttended();
		// Genuinely servicing the errand channel (a park round or collect completed
		// recently AND parking is on), NOT merely awake -- so a peer can exclude a
		// throttled background tab that beats but never collects (peer.js recGenuine).
		var svc = false;
		try { svc = !!(window.DaimondPost && DaimondPost.servicing && DaimondPost.servicing(DaimondPeer.DISPATCH_FRESH_MS)); } catch (e) { svc = false; }
		// THIS MACHINE'S RUNNER POSTURE (runner.js): the nominated device's own
		// answer that it has been set up to stay awake and listening. The nomination
		// says WHERE a hand-off should go; this says the machine named is actually
		// arranged to take one, which until now nothing on the wire distinguished.
		var run = false;
		try { run = !!(window.DaimondRunner && DaimondRunner.on && DaimondRunner.on()); } catch (e) { run = false; }
		// Is this MACHINE a phone or tablet? Sent on EVERY beat, so the election seats
		// a peer on what it is rather than on the name its owner typed -- a phone
		// called "gilgamesh" was seatable, and a desktop window dragged under 760px
		// routed like a phone. Explicit and per-device; the name inference is now only
		// the fallback for a peer on a build that predates the field.
		var mob = isMobileDeviceSelf();
		// THE TWO PLACEMENT FIELDS: does this machine hold the real mounted folder,
		// and can it reach a machine hand. They are what lets ANOTHER device place a
		// compile or a publish without asking -- a phone that cannot hold a book's
		// files hands the layout to a machine that can, and names it before the button
		// is drawn rather than after a failure.
		var fold = selfHoldsFolder();
		var hnd  = selfHoldsHand();
		// HOW BUSY THIS MACHINE IS: the turns it is running or holding (H1). The election
		// on every other device passes a busy machine over for an idle one.
		// The chats that load is in ride with it, so a sender offers this machine for a
		// chat it is already running (the turn queues) and passes it over for others.
		var bsy = 0, bchats = [];
		try { var bh = busyHere(); bsy = DaimondPeer.busyForRec(bh, ''); bchats = bh.busyChats; } catch (e) { bsy = 0; bchats = []; }
		return { id: id, name: name, att: att, svc: svc, run: run, mob: mob, hnd: hnd,
			fold: fold, bsy: bsy, bchats: bchats,
			args: [id, name, att, svc, run, mob, hnd, fold, bsy, bchats] };
	} catch (e) { return null; }
}

/// State this tab's posture: locally at once, then to the gateway. `p` is a posture
/// the caller already read (`postureNow`). Against a gateway that derives presence
/// (HT2, design 2.2), only a CHANGE is stated, so a caller that beats on an event (a
/// turn beginning, the lease ticker) states nothing when nothing moved; against any
/// other gateway it beats as before.
export function presenceTick(p) {
	_beatAt = Date.now();
	try {
		p = p || postureNow();
		if (!p) return;
		if (window.DaimondSync && DaimondSync.presenceDerived && DaimondSync.presenceDerived()
			&& DaimondSync.postureDue && !DaimondSync.postureDue.apply(null, p.args)) return;
		var id = p.id, name = p.name, att = p.att, svc = p.svc, run = p.run, mob = p.mob;
		var hnd = p.hnd, fold = p.fold, bsy = p.bsy, bchats = p.bchats;
		// Optimistic self-update, then beat the gateway on its OWN lightweight,
		// non-waking presence path and adopt the authoritative map it answers
		// with. NOT DaimondSync.push(): presence left the content parcel, so a
		// beat no longer re-uploads ~163K nor wakes every other device -- the
		// defect this replaces. A missed beat is safe.
		_beatBusy = bsy > 0;
		DaimondPresence.beat(id, name, Date.now(), att, svc, null, run, mob, hnd, fold, bsy, bchats);
		// A beat the door could not take yet is OWED, not made. After a reload the first
		// beat comes at unlock, before the gateway has signed this device in, so it sent
		// nothing -- and the next was a whole interval away. For those 45 s every other
		// device read the beat from before the reload: busy with the turn the reload
		// ended, so it was passed over and the phone ran its next turn itself (r545
		// QA-C2 F-C2-1, the second cause). The pulse pays the debt the moment it can.
		var sent = false;
		try {
			if (window.DaimondSync && DaimondSync.beatPresence
				&& (!DaimondSync.canBeat || DaimondSync.canBeat())) {
				sent = true;
				DaimondSync.beatPresence(id, name, att, svc, run, mob, hnd, fold, bsy, bchats);
			}
		} catch (e) { /* the next beat carries it */ }
		_beatOwed = !sent;
		try { notePlaceSeen(); } catch (e) { /* the roster is a convenience, never a gate */ }
		// The seat switch is never more than one beat behind the fleet. The beat and the
		// map it adopts each announce themselves (peer.js), but this device's own beat
		// is also the moment a peer that went quiet ages out of the window.
		try { renderSeatSwitch(); } catch (e) { /* the announcement still redraws it */ }
	} catch (e) { /* a missed beat is safe */ }
}
// page-split: install 68
var PRESENCE_EDGE_MS = 1000;	// how often the edge is read
function presencePulse() {
	// THE BEAT RETIRED (HT2 [M4]): while the gateway derives presence, posture is read
	// every pulse and stated only when it moved (`postureDue`; the `attended` idle
	// decay is such a move), on return to view and on a reconnect. A gateway that
	// does not derive is beaten exactly as below.
	var derived = false;
	try { derived = !!(window.DaimondSync && DaimondSync.presenceDerived && DaimondSync.presenceDerived()); }
	catch (e) { derived = false; }
	if (derived) {
		var p = postureNow();
		var go = false;
		try { go = !!(p && DaimondSync.postureDue.apply(null, p.args)); } catch (e) { go = false; }
		if (go) presenceTick(p);
		return;
	}
	var due = Date.now() - _beatAt >= ((window.DaimondPresence && DaimondPresence.BEAT_MS) || 45000);
	if (!due && _beatBusy != null) {
		var now = false;
		try { now = busyForChat('') > 0; } catch (e) { return; }
		due = now !== _beatBusy;
	}
	if (!due && _beatOwed) {
		try { due = !!(window.DaimondSync && DaimondSync.canBeat && DaimondSync.canBeat()); } catch (e) { due = false; }
	}
	if (due) presenceTick();
}
function startPresenceBeat() {
	if (_presenceTimer) return;
	presenceTick();				// beat now, so a peer sees this device at once
	_presenceTimer = setInterval(presencePulse, PRESENCE_EDGE_MS);
}
function stopPresenceBeat() {
	if (_presenceTimer) clearInterval(_presenceTimer);
	_presenceTimer = null;
}
